from pathlib import Path
p=Path("index.html")
t=p.read_text(encoding="utf-8")

def rep(old,new,count=1):
    global t
    n=t.count(old)
    if n!=count:
        raise SystemExit(f"expected {count}, found {n}: {old[:220]!r}")
    t=t.replace(old,new,count)

rep('<title>볼배틀 리뉴얼 v91</title>','<title>볼배틀 리뉴얼 v92</title>')
rep('<h1 id="mainTitle">볼배틀 리뉴얼 v91</h1>','<h1 id="mainTitle">볼배틀 리뉴얼 v92</h1>')

rep('grooveGainPerSecond: 12.5,','grooveGainPerSecond: 10,')
